    const models = (env.ZHIPU_MODEL?.trim() || 'glm-4.5-flash,glm-4-flash-250414').split(',').map((m) => m.trim()).filter(Boolean);
    return { name: `zhipu/${models.join('→')}`, call: zhipuChain(env.ZHIPU_API_KEY, models) };
  }
