                : e instanceof Anthropic.APIConnectionError
                  ? 'network'
                  : e instanceof Anthropic.APIError
                    ? `api-${e.status}`
                    : e instanceof ProviderError
                      ? e.message.split(':')[0]
                      : 'error';
          trace({ task: body.task, text: body.text, result: reason, error: String(e) });
          send({ source: 'fallback', data: null, reason });
        }
      });
    },
  };
}

