  level: z.enum(['上上', '上', '中', '下']),
  poem: z.array(z.string()),
  read: z.string(),
});

const LetterSchema = z.object({
  item: z.string(),
  to: z.enum(RECIPIENTS.map((r) => r.id) as [string, ...string[]]),
  offer: z.array(z.string()),
  thanks: z.array(z.string()),
